        return ERROR;

    pthread_mutex_lock(&s_clients_mtx);
    ws_client_t* client = find_by_chat_id_locked(chat_id);
    int rc = -1;
    if (client) {
        rc = ws_send_frame(client->fd, json_str, strlen(json_str));
