def _tool_text(m):
    """Tool result JSON -> the raw output text."""
    c = m.get("content")
    if not isinstance(c, str):
        return ""
    try:
        obj = json.loads(c)
        if isinstance(obj, dict):
            return str(obj.get("output") or obj.get("error") or "")
    except Exception:
        pass
    return c


def compose_report(tool_msgs):
    free_txt = route_txt = df_txt = up_txt = ""
    for m in tool_msgs:
        t = _tool_text(m)
        if "total used free" in t and not free_txt:
            free_txt = t
        elif "Uptime" in t:
            up_txt = t
        elif "Filesystem" in t:
            df_txt = t
        elif "Destination" in t or "Iface" in t or "Gateway" in t:
            route_txt = t

    lines = []
    # heap: "<total> <used> <free> ..." from the NuttX `free` table
    for row in free_txt.splitlines():
        parts = row.split()
        if len(parts) >= 3 and parts[0].isdigit():
            total, used, free = (int(parts[0]), int(parts[1]), int(parts[2]))
            lines.append("- 内存: 空闲 %.2f MB / 共 %.2f MB (已用 %.2f MB)"
                         % (free / 1048576.0, total / 1048576.0,
                            used / 1048576.0))
            break
    if up_txt:
        m = re.search(r"Uptime:\s*([0-9.]+)", up_txt)
        if m:
            secs = float(m.group(1))
            lines.append("- 运行时长: %d 分 %d 秒" % (secs // 60, secs % 60))
    if df_txt:
        for row in df_txt.splitlines():
            if "/data" in row:
                parts = row.split()
                if len(parts) >= 4:
                    lines.append("- 存储 /data: 已用 %s / 共 %s"
                                 % (parts[2], parts[1]))
                break
    # a default route line has Destination 0.0.0.0
    net_up = "0.0.0.0" in route_txt and "UG" in route_txt.replace(" ", "")
    lines.append("- 网络: %s" % ("PPP 链路正常" if net_up else "无默认路由"))

    body = "\n".join(lines) if lines else "(未采集到遥测)"
    return ("【设备巡检】\n" + body +
            "\n巡检结论: 各项指标正常，无需处理。")

